Which of the following is a correct way to declare a variable in C?
  1           int x;
  2           x int;
  3        int x = "10";
  4      float x = '10';

#include <stdio.h>
int main() {
   printf("%d", 5 + 3 * 2);
   return 0;
}
  1            11
  2            16
  3            13
  4            8
